stake=[{'registro_id':'F360-APOSTA-20261126-SPFC-REMO-HT-O05','jogo':'São Paulo × Remo','mercado':'Total de Gols do Intervalo','direcao':'Acima','linha':.5,'resultado':'VITORIA','odd':1.82,'valor':1,'pagamento':1.82,'lucro_liquido':.82,'unidade':'unidade Stake','proveniencia':'Bilhete comprovado conforme solicitação explícita do usuário e preliminar; imagem privada não republicada','vinculo_sinal':'F360-PRE-20261126-SPFC-REMO; 1T Gols O0.5; SDD original OBSERVAR preservado'},{'registro_id':'F360-APOSTA-20261126-MULTIPLA-INCOMPLETA','tipo':'Multipla de duas seleções','resultado':'DERROTA','selecoes':None,'odd':None,'valor':None,'pagamento':None,'lucro_liquido':None,'roi_dia':None,'unidade':'unidade Stake','proveniencia':'Bilhete visível segundo relato autorizado; não inferir equipes ou mercados'}]
